def brute(low, high, k):
    cnt = 0
    for n in range(low, high+1):
        s = str(n)
        e = sum(1 for c in s if int(c) % 2 == 0)
        o = len(s) - e
        if e == o and n % k == 0:
            cnt += 1
    return cnt

